#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids, write deduped.jsonl."""

import json


def main():
    seen = set()
    deduped = []

    with open("events.jsonl", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            row = json.loads(line)
            eid = row.get("event_id")
            if eid not in seen:
                seen.add(eid)
                deduped.append(row)

    with open("deduped.jsonl", "w", encoding="utf-8") as f:
        for row in deduped:
            f.write(json.dumps(row, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()

