"""Read events.jsonl from the current directory, remove duplicate events
sharing an event_id (keep first occurrence), and write deduped.jsonl."""

import json


def main() -> None:
    seen: set[str] = set()
    deduped: list[dict] = []

    with open("events.jsonl", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            record = json.loads(line)
            eid = record.get("event_id")
            if eid is not None and eid in seen:
                continue
            if eid is not None:
                seen.add(eid)
            deduped.append(record)

    with open("deduped.jsonl", "w", encoding="utf-8") as out:
        for record in deduped:
            out.write(json.dumps(record, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()

