import json


def load_events(path):
    with open(path, encoding='utf-8') as handle:
        return [json.loads(line) for line in handle if line.strip()]


def dedupe(events):
    seen = set()
    unique = []
    for ev in events:
        eid = ev.get('event_id')
        if eid not in seen:
            seen.add(eid)
            unique.append(ev)
    return unique


def main():
    events = load_events('events.jsonl')
    unique = dedupe(events)
    with open('deduped.jsonl', 'w', encoding='utf-8') as handle:
        for ev in unique:
            handle.write(json.dumps(ev, ensure_ascii=False) + '\n')


if __name__ == '__main__':
    main()

