import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} does not exist")
        return

    manifest = {}
    # Walk all files under release/ (sorted for deterministic output)
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(path)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"wrote {MANIFEST_PATH} with {len(manifest)} entries")


if __name__ == "__main__":
    main()

