"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"report-(\d+)\.txt$", filename)
    if match:
        return int(match.group(1))
    return 0


def main() -> None:
    try:
        files = [f for f in os.listdir(REPORTS_DIR) if re.match(r"report-\d+\.txt$", f)]
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found", file=__import__("sys").stderr)
        __import__("sys").exit(1)

    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

