#!/usr/bin/env python3
"""Print report filenames under reports/ in report order."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_key(filename):
    """Extract the numeric part from a report-<n>.txt filename for sorting."""
    m = re.search(r"report-(\d+)\.txt$", filename)
    if m:
        return int(m.group(1))
    return -1


def main():
    if not os.path.isdir(REPORTS_DIR):
        return

    files = [f for f in os.listdir(REPORTS_DIR) if re.match(r"report-\d+\.txt$", f)]
    files.sort(key=report_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

