#!/usr/bin/env python3
import os
import re
import glob


def report_key(filename):
    """Extract the numeric part from a report filename for sorting."""
    match = re.search(r'report-(\d+)\.txt', filename)
    if match:
        return int(match.group(1))
    return 0


def main():
    report_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'reports')
    pattern = os.path.join(report_dir, 'report-*.txt')
    files = glob.glob(pattern)
    files.sort(key=report_key)
    for f in files:
        print(os.path.basename(f))


if __name__ == '__main__':
    main()

