#!/usr/bin/env python3
"""List files under reports/ in report order (report-1.txt, report-2.txt, ...).

Filenames are report-<n>.txt with n counting up from 1. A directory listing
is not guaranteed to be in any order, so sort by the numeric part of the
name rather than trusting the order returned by os.listdir.
"""

import os
import re

REPORT_DIR = "reports"
NAME_RE = re.compile(r"^report-(\d+)\.txt$")


def sort_key(filename):
    """Return a key that puts report-<n>.txt in numeric order.

    Non-matching files sort after all report files, in plain string order,
    so every file under reports/ is still listed deterministically.
    """
    match = NAME_RE.match(filename)
    if match:
        return (0, int(match.group(1)))
    return (1, filename)


def main():
    files = [
        name
        for name in os.listdir(REPORT_DIR)
        if os.path.isfile(os.path.join(REPORT_DIR, name))
    ]
    for name in sorted(files, key=sort_key):
        print(name)


if __name__ == "__main__":
    main()
