"""Print report file names under reports/, one per line, in report order."""

import os
import re


def list_reports(directory: str = "reports") -> None:
    """Print report filenames sorted by their numerical suffix."""
    files: list[str] = []
    for entry in os.listdir(directory):
        path = os.path.join(directory, entry)
        if os.path.isfile(path):
            files.append(entry)

    def report_key(name: str) -> int:
        match = re.search(r"report-(\d+)", name)
        if match:
            return int(match.group(1))
        return 0

    for name in sorted(files, key=report_key):
        print(name)


if __name__ == "__main__":
    list_reports()

