#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timedelta, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Try to extract a datetime from the YYYY-MM-DD HH:MM:SS prefix."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    app_path = "app.log"
    archive_path = "archive.log"

    # Read all entries from app.log
    with open(app_path) as f:
        lines = f.readlines()

    keep, move = [], []
    for line in lines:
        line = line.rstrip("\n")
        if not line:
            continue
        ts = parse_timestamp(line)
        if ts is None or ts < cutoff:
            move.append(line)
        else:
            keep.append(line)

